import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const arms = ['none', 'devmethod', 'bmad'];
const nonempty = value => typeof value === 'string' && value.trim().length > 0;
const finite = value => typeof value === 'number' && Number.isFinite(value) && value >= 0;
/** Validate a complete matched batch, including blocked/failed runs. Never dispatch models. */
export function summarize(batch) {
  if (!batch || batch.format !== 1 || !Array.isArray(batch.runs) || !batch.runs.length) throw new Error('Expected format 1 nonempty batch');
  const { budget } = batch;
  if (!budget || !Number.isSafeInteger(budget.runs) || budget.runs < 1 || !Number.isSafeInteger(budget.tokens) || budget.tokens < 1 || !finite(budget.costUSD) || !nonempty(budget.authorization)) throw new Error('Explicit run/token/cost budget and authorization required');
  if (batch.runs.length > budget.runs) throw new Error('Run budget exceeded');
  const groups = new Map();
  const matchedKeys = ['fixtureDigest', 'promptDigest', 'hostVersion', 'model', 'toolsDigest', 'permissionsDigest', 'perRunTokens', 'perRunCostUSD', 'timeoutSeconds'];
  const digests = ['fixtureDigest', 'promptDigest', 'toolsDigest', 'permissionsDigest'];
  for (const run of batch.runs) {
    if (!run || !nonempty(run.caseId) || !Number.isSafeInteger(run.repetition) || run.repetition < 1 || !arms.includes(run.arm) || !['passed', 'failed', 'blocked', 'timeout'].includes(run.status)) throw new Error('Invalid run identity or status');
    if (!matchedKeys.every(key => ['perRunTokens', 'perRunCostUSD', 'timeoutSeconds'].includes(key) ? finite(run[key]) && (key === 'perRunCostUSD' || run[key] > 0) : nonempty(run[key])) || !digests.every(key => /^[a-f0-9]{64}$/.test(run[key]))) throw new Error('Missing pinned matched conditions');
    if (!nonempty(run.methodRevision) || !nonempty(run.wrapper) || (run.arm === 'none' && run.methodRevision !== 'none')) throw new Error('Pin method revision and invocation wrapper');
    if (!nonempty(run.evidence) || !nonempty(run.review)) throw new Error('Evidence reference and review or blocked reason required');
    for (const metric of ['tokens', 'costUSD', 'elapsedSeconds']) if (run[metric] !== null && !finite(run[metric])) throw new Error('Usage must be measured nonnegative values or null (unavailable)');
    if ((run.tokens !== null && run.tokens > run.perRunTokens) || (run.costUSD !== null && run.costUSD > run.perRunCostUSD)) throw new Error('Per-run budget exceeded');
    const key = `${run.caseId}:${run.repetition}`;
    const group = groups.get(key) ?? [];
    if (group.some(other => other.arm === run.arm)) throw new Error('Duplicate arm');
    if (group.length && matchedKeys.some(key => run[key] !== group[0][key])) throw new Error('Unmatched conditions');
    group.push(run); groups.set(key, group);
  }
  for (const group of groups.values()) if (group.length !== 3) throw new Error('Each case/repetition requires all three arms, including blocked records');
  for (const metric of ['tokens', 'costUSD']) if (batch.runs.reduce((sum, run) => sum + (run[metric] ?? 0), 0) > budget[metric]) throw new Error('Total budget exceeded');
  const cells = [];
  for (const caseId of new Set(batch.runs.map(run => run.caseId))) for (const arm of arms) {
    const runs = batch.runs.filter(run => run.caseId === caseId && run.arm === arm);
    cells.push({ caseId, arm, denominator: runs.length, ...Object.fromEntries(['passed', 'failed', 'blocked', 'timeout'].map(status => [status, runs.filter(run => run.status === status).length])) });
  }
  return { format: 1, cells, usageComplete: batch.runs.every(run => run.tokens !== null && run.costUSD !== null),
    limitation: 'Validates record consistency only. Evidence authenticity and behavioral claims require independent inspection; no aggregate superiority score.' };
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { if (process.argv.length !== 3) throw new Error('Usage: node scripts/comparison.mjs BATCH_JSON'); console.log(JSON.stringify(summarize(JSON.parse(fs.readFileSync(process.argv[2]))), null, 2)); }
  catch (error) { console.error(error.message); process.exitCode = 2; }
}

import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
export const MAX_REPORT_BYTES = 2 * 1024 * 1024;
export const MAX_ARTIFACT_BYTES = 8 * 1024 * 1024;
const MAX_CAMPAIGN_ARTIFACT_BYTES = 64 * 1024 * 1024;
const directory = fileURLToPath(new URL('../evaluation/behavioral/', import.meta.url));
export const suite = JSON.parse(fs.readFileSync(path.join(directory, 'cases.json')));
export const oracle = JSON.parse(fs.readFileSync(path.join(directory, 'oracle.json')));
const fail = message => { throw new Error(message); };
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const string = x => typeof x === 'string' && x.trim().length > 0;
function shape(value, keys, label) {
  if (!object(value) || Object.keys(value).some(k => !keys.includes(k))) fail(`Malformed ${label}`);
}
function unique(values, label) { if (new Set(values).size !== values.length) fail(`Duplicate ${label}`); }
function array(value, label) { if (!Array.isArray(value)) fail(`Expected array: ${label}`); return value; }
function identifier(value) { if (!string(value) || !/^[A-Za-z0-9._-]+$/.test(value)) fail('Invalid identifier'); }
function timestamp(value) {
  // Require an explicit timezone and reject calendar rollover accepted by Date.parse.
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d{1,3})?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/.test(value)) fail('Invalid timestamps');
  const date = new Date(`${value.slice(0, 10)}T00:00:00Z`);
  const parsed = Date.parse(value);
  if (!Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== value.slice(0, 10) || !Number.isFinite(parsed)) fail('Invalid timestamps');
  return parsed;
}
function validateSuite(spec, expectations) {
  if (spec?.format !== 1 || expectations?.format !== 1 || !Number.isInteger(spec.repetitions) || spec.repetitions < 1) fail('Invalid suite');
  array(spec.cases, 'cases'); array(expectations.cases, 'oracle');
  if (!spec.cases.length) fail('Empty suite');
  unique(spec.cases.map(c => c.id), 'case'); unique(expectations.cases.map(c => c.caseId), 'oracle case');
  if (spec.cases.length !== expectations.cases.length) fail('Oracle coverage mismatch');
  for (const c of spec.cases) {
    identifier(c.id);
    if (!string(c.prompt) || !string(c.setup) || !Number.isInteger(c.minimumSessions) || c.minimumSessions < 1) fail('Malformed case');
    const expected = expectations.cases.find(e => e.caseId === c.id);
    if (!expected || !Array.isArray(expected.criteria) || !expected.criteria.length) fail('Missing oracle criteria');
    unique(expected.criteria.map(e => e.id), 'criterion');
    expected.criteria.forEach(e => { identifier(e.id); if (!string(e.description)) fail('Malformed criterion'); });
  }
}
function artifactCheck(artifact, artifactRoot, budget) {
  shape(artifact, ['id', 'path', 'sha256', 'kind'], 'artifact'); identifier(artifact.id);
  if (!['transcript', 'snapshot', 'check', 'adjudication'].includes(artifact.kind) || !/^[a-f0-9]{64}$/.test(artifact.sha256)) fail('Invalid artifact digest/kind');
  if (!string(artifact.path) || path.isAbsolute(artifact.path) || artifact.path.includes('\\') || artifact.path.split('/').some(p => !p || p === '..' || p === '.')) fail('Unsafe artifact path');
  if (!artifactRoot) fail('Evidence requires an artifact root');
  const root = fs.realpathSync(artifactRoot);
  let current = root;
  for (const part of artifact.path.split('/')) {
    current = path.join(current, part);
    if (fs.lstatSync(current).isSymbolicLink()) fail('Symbolic artifact path');
  }
  const stat = fs.statSync(current);
  if (!stat.isFile()) fail('Artifact is not a regular file');
  if (stat.size > MAX_ARTIFACT_BYTES || budget.bytes + stat.size > MAX_CAMPAIGN_ARTIFACT_BYTES) fail('Artifact size limit exceeded');
  budget.bytes += stat.size;
  const bytes = fs.readFileSync(current);
  if (!bytes.length || createHash('sha256').update(bytes).digest('hex') !== artifact.sha256) fail('Artifact hash mismatch or empty artifact');
}
/** Scores explicit, separately adjudicated observations. Never executes report text or dispatches agents. */
export function scoreBehavior(report, { spec = suite, expectations = oracle, artifactRoot } = {}) {
  validateSuite(spec, expectations);
  shape(report, ['format', 'runs'], 'report');
  if (report.format !== 1) fail('Unsupported report format');
  array(report.runs, 'runs');
  const slots = new Map(); const ids = new Set();
  let nativeConfiguration;
  const fixtureRevisions = new Map();
  const nativeTranscriptPaths = new Set(), nativeTranscriptHashes = new Set();
  const artifactBudget = { bytes: 0 };
  for (const run of report.runs) {
    shape(run, ['id', 'caseId', 'repetition', 'status', 'kind', 'reason', 'provenance', 'artifacts', 'judgments', 'metrics'], 'run');
    identifier(run.id);
    if (ids.has(run.id)) fail('Duplicate run id'); ids.add(run.id);
    const c = spec.cases.find(c => c.id === run.caseId);
    if (!c || !Number.isInteger(run.repetition) || run.repetition < 1 || run.repetition > spec.repetitions) fail('Unknown case or repetition');
    const key = `${run.caseId}:${run.repetition}`;
    if (slots.has(key)) fail('Duplicate run slot');
    if (!['completed', 'blocked', 'interrupted', 'not-run'].includes(run.status) || !['native', 'synthetic'].includes(run.kind)) fail('Invalid run status/kind');
    if (run.status !== 'completed' && !string(run.reason)) fail('Unfinished run requires reason');
    array(run.artifacts, 'artifacts'); unique(run.artifacts.map(a => a.id), 'artifact');
    run.artifacts.forEach(a => artifactCheck(a, artifactRoot, artifactBudget));
    const artifacts = new Map(run.artifacts.map(a => [a.id, a]));
    if (run.kind === 'native' && !['not-run', 'blocked'].includes(run.status)) {
      shape(run.provenance, ['host', 'hostVersion', 'model', 'methodRevision', 'fixtureRevision', 'permissions', 'startedAt', 'endedAt', 'sessions', 'adjudicator'], 'provenance');
      for (const field of ['host', 'hostVersion', 'model', 'methodRevision', 'fixtureRevision', 'permissions', 'adjudicator']) if (!string(run.provenance[field])) fail(`Missing provenance ${field}`);
      const p = run.provenance;
      const configuration = JSON.stringify(['host', 'hostVersion', 'model', 'methodRevision', 'permissions'].map(k => p[k]));
      if (nativeConfiguration && nativeConfiguration !== configuration) fail('Mixed native configurations require separate reports');
      nativeConfiguration = configuration;
      if (fixtureRevisions.has(run.caseId) && fixtureRevisions.get(run.caseId) !== p.fixtureRevision) fail('Mixed fixture revisions for the same case');
      fixtureRevisions.set(run.caseId, p.fixtureRevision);
      if (timestamp(p.endedAt) < timestamp(p.startedAt)) fail('Invalid timestamps');
      array(p.sessions, 'sessions'); unique(p.sessions.map(s => s.id), 'session'); unique(p.sessions.map(s => s.transcriptId), 'session transcript');
      if (!p.sessions.length || (run.status === 'completed' && p.sessions.length < c.minimumSessions)) fail('Insufficient actual sessions');
      for (const s of p.sessions) { shape(s, ['id', 'transcriptId'], 'session'); identifier(s.id); if (artifacts.get(s.transcriptId)?.kind !== 'transcript') fail('Missing session transcript'); }
      unique(p.sessions.map(s => artifacts.get(s.transcriptId).path), 'session transcript path');
      unique(p.sessions.map(s => artifacts.get(s.transcriptId).sha256), 'session transcript bytes');
      for (const s of p.sessions) {
        const transcript = artifacts.get(s.transcriptId);
        if (nativeTranscriptPaths.has(transcript.path) || nativeTranscriptHashes.has(transcript.sha256)) fail('Reused native session transcript across runs');
        nativeTranscriptPaths.add(transcript.path); nativeTranscriptHashes.add(transcript.sha256);
      }
    }
    const expected = expectations.cases.find(e => e.caseId === c.id).criteria;
    array(run.judgments, 'judgments'); unique(run.judgments.map(j => j.criterionId), 'judgment');
    for (const j of run.judgments) {
      shape(j, ['criterionId', 'verdict', 'justification', 'evidenceIds'], 'judgment');
      if (!expected.some(e => e.id === j.criterionId) || !['pass', 'fail', 'unresolved'].includes(j.verdict) || !string(j.justification)) fail('Invalid judgment');
      array(j.evidenceIds, 'evidence references'); unique(j.evidenceIds, 'evidence reference');
      if (j.evidenceIds.some(id => !artifacts.has(id)) || (j.verdict !== 'unresolved' && !j.evidenceIds.length)) fail('Missing or unknown judgment evidence');
    }
    shape(run.metrics, ['humanInterventions', 'tokens', 'elapsedMs', 'costUsd'], 'metrics');
    for (const field of ['humanInterventions', 'tokens', 'elapsedMs', 'costUsd']) {
      const value = run.metrics[field];
      if (value !== null && (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || (['humanInterventions', 'tokens'].includes(field) && !Number.isSafeInteger(value)))) fail(`Invalid metric ${field}; counts must be safe integers and unknown must be null`);
    }
    slots.set(key, run);
  }
  const rows = [];
  for (const c of spec.cases) for (let repetition = 1; repetition <= spec.repetitions; repetition++) {
    const run = slots.get(`${c.id}:${repetition}`);
    const criteria = expectations.cases.find(e => e.caseId === c.id).criteria;
    const missing = criteria.filter(e => !run?.judgments.some(j => j.criterionId === e.id)).map(e => e.id);
    let outcome = run?.status ?? 'not-run';
    if (run?.status === 'completed') outcome = run.judgments.some(j => j.verdict === 'fail') ? 'failed' : missing.length || run.judgments.some(j => j.verdict === 'unresolved') ? 'unresolved' : 'passed';
    rows.push({ caseId: c.id, repetition, kind: run?.kind ?? null, outcome, missingCriteria: missing });
  }
  const native = rows.filter(r => r.kind === 'native');
  const completed = native.filter(r => ['passed', 'failed', 'unresolved'].includes(r.outcome));
  const passed = native.filter(r => r.outcome === 'passed').length;
  const metrics = {};
  for (const field of ['humanInterventions', 'tokens', 'elapsedMs', 'costUsd']) {
    const attempted = [...slots.values()].filter(r => r.kind === 'native' && !['not-run', 'blocked'].includes(r.status));
    const known = attempted.map(r => r.metrics[field]).filter(v => v !== null);
    const observedTotal = known.length ? known.reduce((total, value) => {
      const next = total + value;
      if (!Number.isFinite(next) || (['humanInterventions', 'tokens'].includes(field) && !Number.isSafeInteger(next))) fail(`Metric total exceeds numeric range: ${field}`);
      return next;
    }, 0) : null;
    metrics[field] = { knownRuns: known.length, unknownRuns: attempted.length - known.length, observedTotal };
  }
  return { format: 1, plannedRuns: rows.length, submittedRuns: report.runs.length, nativeCompletedRuns: completed.length,
    nativePassedRuns: passed, nativePassFractionOfPlan: passed / rows.length,
    nativePassRateAmongCompleted: completed.length ? passed / completed.length : null,
    outcomes: Object.fromEntries(['passed', 'failed', 'unresolved', 'not-run', 'blocked', 'interrupted'].map(k => [k, rows.filter(r => r.outcome === k).length])),
    syntheticRuns: rows.filter(r => r.kind === 'synthetic').length, metrics, rows,
    limitation: 'Hashes establish artifact integrity, not authenticity or judge correctness. Synthetic calibration is not model performance. Independent adjudication and repeated native runs are required.' };
}
if (process.argv[1] && path.relative(fileURLToPath(import.meta.url), path.resolve(process.argv[1])) === '') {
  try {
    const [file, artifactRoot, ...extra] = process.argv.slice(2);
    if (!file || extra.length) fail('Usage: node scripts/evaluate-behavior.mjs REPORT.json [ARTIFACT_ROOT]');
    const stat = fs.statSync(file);
    if (!stat.isFile() || stat.size > MAX_REPORT_BYTES) fail('Report must be a regular file within the report size limit');
    console.log(JSON.stringify(scoreBehavior(JSON.parse(fs.readFileSync(file, 'utf8')), { artifactRoot }), null, 2));
  } catch (error) { console.error(error.message); process.exitCode = 2; }
}

/** Reconcile a complete private app-server stream; cumulative totals are not deltas. */
export function meterCodexTree(events, root) {
  const ids=new Set([root]), totals=new Map(), active=new Map(), ended=new Set();
  for(const e of events) {
    const p=e.params ?? {}, item=p.item;
    if(item?.type==='subAgentActivity' && ids.has(p.threadId)) ids.add(item.agentThreadId);
    if(e.method==='thread/started' && ids.has(p.thread?.parentThreadId))ids.add(p.thread.id);
    if(e.method==='thread/tokenUsage/updated')totals.set(p.threadId,p.tokenUsage?.total);
    if(e.method==='turn/started'){active.set(p.threadId,p.turn.id);ended.delete(p.threadId);}
    if(e.method==='turn/completed'){active.delete(p.threadId);ended.add(p.threadId);}
  }
  const missing=[...ids].filter(id=>!id || !ended.has(id) || active.has(id) || !['inputTokens','outputTokens'].every(k=>Number.isSafeInteger(totals.get(id)?.[k]) && totals.get(id)[k]>=0));
  // Usage for an undiscovered thread means attribution is incomplete.
  for(const id of totals.keys())if(!ids.has(id))missing.push(id);
  const usage=missing.length?null:{inputTokens:[...ids].reduce((n,id)=>n+totals.get(id).inputTokens,0),outputTokens:[...ids].reduce((n,id)=>n+totals.get(id).outputTokens,0),costUSD:null};
  return {threads:[...ids],missing,usage};
}

import { spawn } from 'node:child_process';
import { codexEnvironment } from './codex.mjs';

/** Private stdio server, bounded lifetime. Never attaches to the desktop daemon. */
export function startCodexRpc({ cwd, timeoutMs = 120000, onEvent = () => {}, command = 'codex', args = ['app-server', '--stdio', '--disable', 'apps', '--disable', 'plugins', '--disable', 'remote_plugin'] }) {
  if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 120000) throw new Error('Invalid RPC lifetime');
  const child = spawn(command, args,
    { cwd, env: codexEnvironment(), detached: process.platform !== 'win32', stdio: ['pipe', 'pipe', 'pipe'] });
  const pending = new Map(); let next = 0, buffer = '', bytes = 0, stopped = false;
  const kill = () => { try { process.platform === 'win32' ? child.kill('SIGKILL') : process.kill(-child.pid, 'SIGKILL'); } catch {} };
  function close(error = new Error('RPC server closed')) {
    if (stopped) return; stopped = true; clearTimeout(timer); process.removeListener('exit',kill); kill();
    for (const { reject } of pending.values()) reject(error); pending.clear();
  }
  process.once('exit',kill);
  const timer = setTimeout(() => close(new Error('RPC lifetime exceeded')), timeoutMs);
  function send(message) { if (stopped) throw new Error('RPC closed'); child.stdin.write(JSON.stringify(message)+'\n'); }
  child.stdout.setEncoding('utf8');
  child.stdout.on('data', chunk => {
    bytes += Buffer.byteLength(chunk); if (bytes > 2*1024*1024) return close(new Error('RPC output limit'));
    buffer += chunk;
    let end;
    while ((end = buffer.indexOf('\n')) >= 0) {
      const line = buffer.slice(0,end); buffer = buffer.slice(end+1); if (!line.trim()) continue;
      try {
        const message = JSON.parse(line);
        if ('id' in message && !message.method) {
          const call = pending.get(message.id); if (!call) continue; pending.delete(message.id);
          message.error ? call.reject(new Error(JSON.stringify(message.error))) : call.resolve(message.result);
        } else if ('id' in message) {
          // Unattended probes never approve tool execution or fulfill external requests.
          send({ id: message.id, error: { code: -32601, message: 'Client requests disabled in probe' } });
        } else onEvent(message);
      } catch (error) { close(error); }
    }
  });
  child.stderr.on('data', chunk => { bytes += chunk.length; if (bytes > 2*1024*1024) close(new Error('RPC output limit')); });
  child.on('error', close); child.on('close', () => close()); child.stdin.on('error', close);
  return { close, notify: send, call(method, params = {}) {
    if (stopped) return Promise.reject(new Error('RPC closed'));
    const id = ++next;
    return new Promise((resolve,reject) => { pending.set(id,{resolve,reject}); send({ id, method, params }); });
  } };
}

import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { checkPath } from '../dist/filesystem.js';

const recordObject = value => typeof value === 'object' && value !== null && !Array.isArray(value);
function observedTokens(usage) {
  if (!recordObject(usage) || !['inputTokens', 'outputTokens'].every(key => Number.isSafeInteger(usage[key]) && usage[key] >= 0))
    throw new Error('Malformed or unknown usage requires reconciliation.');
  const total = usage.inputTokens + usage.outputTokens;
  if (!Number.isSafeInteger(total)) throw new Error('Usage total exceeds safe integer range; reconciliation required.');
  return total;
}

/** Bounded process supervision. Success means process exit, not task acceptance. */
export async function supervise({ command, args, cwd, prompt, timeoutMs, signal, env, maxBytes = 2 * 1024 * 1024 }) {
  if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 120000) throw new Error('Timeout must be 1–120000 ms.');
  if (signal?.aborted) return { status: 'cancelled', exit: null, stdout: '', stderr: '', elapsedSeconds: 0 };
  const start = Date.now();
  return await new Promise(resolve => {
    const child = spawn(command, args, { cwd, env, detached: process.platform !== 'win32', stdio: ['pipe', 'pipe', 'pipe'] });
    let stdout = '', stderr = '', bytes = 0, stopped, killTimer, settled = false;
    const kill = name => { try { if (process.platform !== 'win32') process.kill(-child.pid, name); else child.kill(name); } catch {} };
    const stop = reason => { if (stopped) return; stopped = reason; kill('SIGTERM'); killTimer = setTimeout(() => kill('SIGKILL'), 1500); };
    const timer = setTimeout(() => stop('timeout'), timeoutMs);
    const cancel = () => stop('cancelled'); signal?.addEventListener('abort', cancel, { once: true });
    const finish = (exit, error) => {
      if (settled) return; settled = true; clearTimeout(timer); clearTimeout(killTimer); signal?.removeEventListener('abort', cancel);
      // Terminate remaining descendants even if the direct child already exited.
      if (process.platform !== 'win32') kill('SIGKILL');
      resolve({ status: stopped ?? (error ? 'unavailable' : exit === 0 ? 'exited' : 'failed'), exit, error: error?.message,
        stdout, stderr, elapsedSeconds: (Date.now()-start)/1000 });
    };
    const read = (chunk, kind) => { bytes += Buffer.byteLength(chunk); if (bytes > maxBytes) { stop('output-limit'); return; }
      if (kind === 'out') stdout += chunk.toString(); else stderr += chunk.toString(); };
    child.stdout.setEncoding('utf8'); child.stderr.setEncoding('utf8');
    child.stdout.on('data', c => read(c,'out')); child.stderr.on('data', c => read(c,'err'));
    child.once('error', e => finish(null,e)); child.once('close', code => finish(code));
    child.stdin.on('error', () => {}); child.stdin.end(prompt);
  });
}
/** Immutable per-run slots avoid blind retries. Ledger lives outside worker writable roots. */
export function reserveRun(ledgerRoot, id, { maxRuns = 12, observedTokenStop = 500000 } = {}) {
  if (!Number.isInteger(maxRuns) || maxRuns < 1 || maxRuns > 12 || !Number.isSafeInteger(observedTokenStop) || observedTokenStop < 1 || observedTokenStop > 500000) throw new Error('Invalid bounded pilot limits.');
  if (!/^[a-zA-Z0-9-]{1,64}$/.test(id)) throw new Error('Invalid run ID.');
  checkPath(path.resolve(ledgerRoot)); fs.mkdirSync(ledgerRoot, { recursive: true });
  const lock = path.join(ledgerRoot, '.lock'); const fd = fs.openSync(lock, 'wx');
  try {
    const records = fs.readdirSync(ledgerRoot).filter(n=>n.endsWith('.json')).map(n=>JSON.parse(fs.readFileSync(path.join(ledgerRoot,n),'utf8')));
    if (records.length >= maxRuns) throw new Error('Run limit reached.');
    if (records.some(r=>!recordObject(r) || !['exited','failed'].includes(r.status) || r.usage === null)) throw new Error('Interrupted, cancelled, unavailable or unmetered run requires reconciliation; no automatic retry.');
    const used = records.reduce((n,r)=> {
      const total = n + observedTokens(r.usage);
      if (!Number.isSafeInteger(total)) throw new Error('Usage total exceeds safe integer range; reconciliation required.');
      return total;
    },0);
    if (used >= observedTokenStop) throw new Error('Observed token stop reached. This is an inter-run stop, not a per-request cap.');
    const file = path.join(ledgerRoot, `${id}.json`);
    fs.writeFileSync(file, JSON.stringify({ id, status: 'running', usage: null }), { flag: 'wx' }); return file;
  } finally { fs.closeSync(fd); fs.unlinkSync(lock); }
}
export function recordRun(file, result) {
  checkPath(path.resolve(file));
  const previous = JSON.parse(fs.readFileSync(file));
  if (previous.status !== 'running') throw new Error('Run already finalized.');
  if (!recordObject(result) || !['exited','failed','unavailable','cancelled','interrupted','incomplete','timeout','output-limit'].includes(result.status))
    throw new Error('Expected a terminal run status; reconciliation required.');
  if (result.usage !== null) observedTokens(result.usage);
  const temporary = `${file}.tmp`;
