import * as fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { parseJson, checkPath } from './filesystem.js';
import { gitState, validGit, type GitState } from './records.js';

export interface CheckpointSource { id: string; path: string; sha256: string }
export interface CheckpointEvidence extends CheckpointSource {
  sourceIds: string[];
  dependsOn: string[];
  outcome: 'passed' | 'failed' | 'blocked' | 'not-run';
  criterionIds?: string[];
  kind?: 'automated' | 'manual' | 'design-review' | 'recommendation';
  revision?: string;
}
export interface Checkpoint {
  format: 1;
  git?: GitState;
  blockers?: string[];
  scope: string;
  status: 'active' | 'blocked' | 'complete';
  nextAction: string | null;
  sources: CheckpointSource[];
  evidence: CheckpointEvidence[];
}
export interface CheckpointFinding { code: string; message: string; id?: string; path?: string }
export interface CheckpointReport {
  format: 1;
  destination: string;
  status: 'ready' | 'reverify' | 'blocked' | 'complete' | 'invalid';
  scope?: string;
  nextAction?: string | null;
  findings: CheckpointFinding[];
  sources: { id: string; state: 'unchanged' | 'changed' | 'unavailable' }[];
  evidence: { id: string; state: 'valid' | 'invalidated' | 'failed' | 'blocked' | 'not-run' }[];
}

const object = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);
const identifier = (value: unknown): value is string =>
  typeof value === 'string' && /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}$/.test(value);
const nonempty = (value: unknown): value is string => typeof value === 'string' && value.trim().length > 0;
// Portable repository-relative paths only: no Windows aliases, drives or streams.
function safePath(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0 && !/[\\:\x00-\x1f\x7f]/.test(value)
    && value.split('/').every(part => part.length > 0 && part !== '.' && part !== '..'
      && !/[. ]$/.test(part) && !/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(part));
}
function pinned(value: unknown): value is CheckpointSource {
  return object(value) && identifier(value.id) && safePath(value.path)
    && typeof value.sha256 === 'string' && /^[a-f0-9]{64}$/.test(value.sha256);
}
function ids(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(identifier) && new Set(value).size === value.length;
}
function validate(input: unknown): Checkpoint {
  if (!object(input) || input.format !== 1) throw new Error('Expected checkpoint format 1. Markdown checkpoints remain a manual workflow.');
  if (!nonempty(input.scope) || typeof input.status !== 'string' || !['active', 'blocked', 'complete'].includes(input.status))
    throw new Error('Checkpoint needs a nonempty scope and status active, blocked or complete.');
  if (input.nextAction !== null && !nonempty(input.nextAction)) throw new Error('nextAction must be a nonempty string or null.');
  if (input.status === 'complete' && input.nextAction !== null) throw new Error('Completed scope must have nextAction null; completion authorizes no new work.');
  if (input.status !== 'complete' && !nonempty(input.nextAction)) throw new Error('Active or blocked scope needs an explicit nextAction.');
  if (!Array.isArray(input.sources) || !input.sources.every(pinned) || input.sources.length === 0)
    throw new Error('sources must contain pinned IDs, safe relative paths and lowercase SHA-256 hashes.');
  if (!Array.isArray(input.evidence) || !input.evidence.every(item => pinned(item) && object(item)
    && ids(item.sourceIds) && item.sourceIds.length > 0 && ids(item.dependsOn)
    && typeof item.outcome === 'string' && ['passed', 'failed', 'blocked', 'not-run'].includes(item.outcome)))
    throw new Error('evidence needs pinned artifacts, sourceIds, dependsOn and outcome passed, failed or not-run.');
  if (input.sources.length > 256 || input.evidence.length > 256) throw new Error('Checkpoint supports at most 256 sources and evidence items.');
  if (input.git !== undefined && !validGit(input.git)) throw new Error('Invalid Git checkpoint provenance.');
  if (input.blockers !== undefined && (!Array.isArray(input.blockers) || !input.blockers.every(nonempty))) throw new Error('blockers must be nonempty strings.');
  for (const item of input.evidence) {
    if (item.criterionIds !== undefined && (!ids(item.criterionIds) || !item.criterionIds.length)) throw new Error('criterionIds must be nonempty unique IDs.');
    if (item.kind !== undefined && (typeof item.kind !== 'string' || !['automated', 'manual', 'design-review', 'recommendation'].includes(item.kind))) throw new Error('Invalid verification kind.');
    if (item.revision !== undefined && !nonempty(item.revision)) throw new Error('Invalid evidence revision.');
  }
  const state = input as unknown as Checkpoint;
  const sources = new Set(state.sources.map(source => source.id));
  const evidence = new Map(state.evidence.map(item => [item.id, item]));
  if (sources.size !== state.sources.length || evidence.size !== state.evidence.length)
    throw new Error('Source IDs and evidence IDs must each be unique.');
  if (new Set(state.sources.map(source => source.path)).size !== state.sources.length
    || new Set(state.evidence.map(item => item.path)).size !== state.evidence.length)
    throw new Error('Source paths and evidence paths must each be unique.');
  for (const item of state.evidence) {
    if (item.sourceIds.some(id => !sources.has(id)) || item.dependsOn.some(id => !evidence.has(id)))
      throw new Error(`Evidence ${item.id} references an unknown source or evidence ID.`);
  }
  // Iterative topological traversal avoids stack exhaustion on an untrusted graph.
  const done = new Set<string>();
  while (done.size < evidence.size) {
    let progress = false;
    for (const item of state.evidence) if (!done.has(item.id) && item.dependsOn.every(id => done.has(id))) {
      done.add(item.id); progress = true;
    }
