}

function readPinned(destination: string, relative: string): Buffer {
  if (!safePath(relative)) throw new Error('Expected a safe repository-relative path.');
  const file = path.join(destination, relative);
  checkPath(file);
  if (!fs.lstatSync(file).isFile() || fs.lstatSync(file).size > 1024 * 1024) throw new Error('Expected a regular file.');
  return fs.readFileSync(file);
}
function emptyReport(destination: string): CheckpointReport {
  return { format: 1, destination: path.resolve(destination), status: 'invalid', findings: [], sources: [], evidence: [] };
}

/** Read-only inspection; report readiness never grants execution or integration permission. */
export function inspectCheckpoint(destination: string, input: unknown): CheckpointReport {
  const report = emptyReport(destination);
  let state: Checkpoint;
  try {
    state = validate(input);
    checkPath(report.destination);
    if (!fs.statSync(report.destination).isDirectory()) throw new Error('Destination must be a directory.');
  } catch (error) {
    report.findings.push({ code: 'invalid-checkpoint', message: (error as Error).message });
    return report;
  }
  report.scope = state.scope;
  report.nextAction = state.nextAction;
  const compare = (item: CheckpointSource, kind: 'source' | 'evidence'): 'unchanged' | 'changed' | 'unavailable' => {
    try {
      const digest = createHash('sha256').update(readPinned(report.destination, item.path)).digest('hex');
      if (digest === item.sha256) return 'unchanged';
      report.findings.push({ code: `${kind}-changed`, id: item.id, path: item.path, message: `Pinned ${kind} content changed; inspect the difference and repeat affected verification.` });
      return 'changed';
    } catch (error) {
      report.findings.push({ code: `${kind}-unavailable`, id: item.id, path: item.path, message: `Cannot inspect pinned ${kind}: ${(error as Error).message}` });
      return 'unavailable';
    }
  };
  report.sources = state.sources.map(source => ({ id: source.id, state: compare(source, 'source') }));
  const sourceStates = new Map(report.sources.map(source => [source.id, source.state]));
  const artifactStates = new Map(state.evidence.map(item => [item.id, compare(item, 'evidence')]));
  const evidenceStates = new Map<string, CheckpointReport['evidence'][number]['state']>();
  while (evidenceStates.size < state.evidence.length) {
    for (const item of state.evidence) {
      if (evidenceStates.has(item.id) || !item.dependsOn.every(id => evidenceStates.has(id))) continue;
      const invalidated = artifactStates.get(item.id) !== 'unchanged'
        || item.sourceIds.some(id => sourceStates.get(id) !== 'unchanged')
        || item.dependsOn.some(id => evidenceStates.get(id) !== 'valid');
      const result = invalidated ? 'invalidated' : item.outcome === 'passed' ? 'valid' : item.outcome;
      evidenceStates.set(item.id, result);
      if (result !== 'valid') report.findings.push({ code: `evidence-${result}`, id: item.id, path: item.path,
        message: `Evidence ${item.id} is ${result}; it cannot support resumption until affected verification is recorded again.` });
    }
  }
  report.evidence = state.evidence.map(item => ({ id: item.id, state: evidenceStates.get(item.id)! }));
  let gitChanged = false;
  if (state.git) {
    try {
      const current = gitState(report.destination);
      gitChanged = Object.entries(state.git).some(([key, value]) => current[key as keyof GitState] !== value);
      if (gitChanged) report.findings.push({ code: 'git-changed', message: 'Branch, commit or worktree changed; reassess scope and omitted dependencies. Independent pins are retained.' });
    } catch { gitChanged = true; report.findings.push({ code: 'git-unavailable', message: 'Cannot compare recorded Git provenance.' }); }
  }
  for (const blocker of state.blockers ?? []) report.findings.push({ code: 'dependency-blocked', message: blocker });
  const needsVerification = gitChanged || report.sources.some(source => source.state !== 'unchanged')
    || report.evidence.some(item => item.state !== 'valid') || report.evidence.length === 0;
  if (!report.evidence.length) report.findings.push({ code: 'evidence-empty', message: 'No evidence was pinned; establish verification before relying on this checkpoint.' });
  report.status = state.status === 'blocked' || (state.blockers?.length ?? 0) > 0 || state.evidence.some(item => item.outcome === 'blocked') ? 'blocked' : needsVerification ? 'reverify' : state.status === 'complete' ? 'complete' : 'ready';
  return report;
}

/** Load a JSON checkpoint within the project; never follows symbolic paths or changes files. */
export function readCheckpoint(destination: string, checkpointPath: string): CheckpointReport {
  try {
    return inspectCheckpoint(destination, parseJson(readPinned(path.resolve(destination), checkpointPath).toString('utf8')));
  } catch (error) {
    const report = emptyReport(destination);
    report.findings.push({ code: 'invalid-checkpoint', path: checkpointPath, message: (error as Error).message });
    return report;
  }
}

