export const secretPath = (v: string): boolean => /(^|\/)(\.env(?:\..*)?|\.git|\.ssh|\.npmrc|credentials(?:\..*)?|secrets?(?:\..*)?)(\/|$)|\.(pem|key|p12|pfx)$/i.test(v);
export function readLocal(root: string, file: string, limit = 1024 * 1024): Buffer {
