export function reviewMarkdown(r: Review): string {
  const s = summarizeReview(r);
  const lines = [`# ${md(r.title)}`, '', `${md(r.project)} · ${md(r.mission)} · ${md(r.date)}`, `Revision: ${md(r.revision.commit)}; uncommitted changes: ${r.revision.dirty.map(md).join(', ') || 'none recorded'}`, '', `Conclusion: **${conclusionLabels[s.conclusion]}**`, md(r.summary), `Policy: ${md(r.policy.rationale)}`, '', '## Scope', ...r.scope.map(v => `- ${md(v)}`), '', '## Exclusions and limits', ...[...r.exclusions, ...r.limits].map(v => `- ${md(v)}`), '', '## Counts (whole review)', ...Object.entries(s.severities).map(([severity, count]) => `- ${severityLabels[severity as Severity]}: ${count}`), `- À vérifier: ${s.suspected}`, ...Object.entries(s.checks).map(([status, count]) => `- ${checkLabels[status as CheckStatus]}: ${count}`), '', '## Coverage', ...r.checks.map(c => `- **${md(c.id)} — ${md(c.title)}** (${md(c.domain)}, ${c.kind}): ${checkLabels[c.status]}. ${md(c.result)}${c.reason ? ` Reason: ${md(c.reason)}` : ''} Revision: ${md(c.revision)}. Evidence: ${c.evidenceIds.map(md).join(', ') || 'none'}`), '', '## Findings'];
  for (const f of r.findings) lines.push('', `### ${md(f.id)} — ${md(f.title)}`, `${severityLabels[f.severity]} / ${confidenceLabels[f.confidence]} / ${resolutionLabels[f.resolution]}`, `Severity rationale: ${md(f.severityReason)}`, `Location: ${md(f.location.path)}${f.location.line ? `:${f.location.line}` : ''}`, `Impact: ${md(f.impact)}`, `Trigger: ${md(f.trigger)}`, `Expected: ${md(f.expected)}`, `Observed: ${md(f.observed)}`, 'Reproduction:', ...f.reproduction.map(v => `- ${md(v)}`), `Evidence: ${f.evidenceIds.map(md).join(', ') || 'none'}`, `Correction: ${md(f.correction)}`, `Trade-offs: ${md(f.tradeoffs)}`, `Resolution verification: ${md(f.verification)}`, `Resolution evidence: ${f.resolutionEvidenceIds.map(md).join(', ') || 'none'}`, `Sources: ${f.sourceIds.map(md).join(', ') || 'none'}`, `Tickets: ${f.ticketIds.map(md).join(', ') || 'none'}`);
  lines.push('', '## Evidence');
  for (const e of r.evidence) lines.push('', `### ${md(e.id)} — ${md(e.title)}`, `${e.kind}${e.image ? ` (${e.image.origin}; image is embedded in HTML/JSON, text alternative: ${md(e.image.alt)})` : ''}`, md(e.content), e.url ? `Full evidence: ${e.url}` : 'No external evidence destination.');
  lines.push('', '## Sources');
  for (const source of r.sources) lines.push(`- ${md(source.id)}: ${md(source.title)} — ${md(source.publisher)}; ${md(source.technology)} ${md(source.version)}; ${source.access}; ${source.consultedAt || 'not consulted'}; ${source.url || 'no destination'}. ${md(source.usage)} Compatibility: ${md(source.compatibility)} Provenance: ${md(source.provenance)}`);
  lines.push('', '## Technologies', ...r.technologies.map(t => `- ${md(t.name)} ${md(t.version)} (${md(t.detectedFrom)})`), '', '## Tickets', ...r.tickets.map(t => `- ${md(t.id)} — ${md(t.title)}: ${t.url || 'no published destination'}`), '', 'Generated from review format 1. Counts describe the whole review. Historical evidence does not certify a later revision.', '');
  return lines.join('\n');
}

import * as fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { bundledFiles, bundledProvenance, type Provenance } from './init.js';
import { diagnose, validateManifest } from './doctor.js';
import { parseJson, checkPath, stat } from './filesystem.js';

type Entry = {
  path: string; classification: 'unchanged' | 'updated' | 'customized' | 'conflict' | 'added' | 'removed';
  installedSha256?: string; baselineSha256?: string; candidateSha256?: string;
  candidateChanged: boolean; missing?: boolean; collision?: boolean;
};
export type UpdateReport = {
  format: 1; destination: string; status: 'ok' | 'warning' | 'error';
  installed?: Provenance; candidate?: Provenance; provenance: 'recorded' | 'unknown';
  entries: Entry[]; findings: { code: string; path?: string; message: string }[];
};
const hash = (data: Buffer) => createHash('sha256').update(data).digest('hex');

/** Preview only. No staging writes, migrations, subprocesses, or network calls. */
export function previewUpdate(destination: string): UpdateReport {
  const report: UpdateReport = { format: 1, destination: path.resolve(destination), status: 'ok', provenance: 'unknown', entries: [], findings: [] };
  try {
    const diagnostics = diagnose(report.destination);
    report.findings.push(...diagnostics.findings);
    report.status = diagnostics.status;
    // Missing files are represented in the comparison, but remain diagnostic errors.
    if (diagnostics.findings.some(f => f.severity === 'error' && f.code !== 'file-missing')) return report;
    const manifestPath = path.join(report.destination, 'kit-manifest.json');
    checkPath(manifestPath);
    const info = stat(manifestPath);
    if (!info?.isFile() || info.size > 1024 * 1024) throw new Error('Invalid manifest file.');
    const manifest = validateManifest(parseJson(fs.readFileSync(manifestPath, 'utf8')));
    report.installed = manifest.provenance;
    report.provenance = manifest.provenance ? 'recorded' : 'unknown';
    if (!manifest.provenance) {
      if (report.status === 'ok') report.status = 'warning';
      report.findings.push({ code: 'provenance-unknown', message: 'Legacy installation: package version is unknown; recorded file hashes remain the comparison baseline.' });
    }
    const candidate = bundledFiles(manifest.tool, manifest.skills);
    const hashes = Object.fromEntries([...candidate].map(([name, data]) => [name, hash(data)]));
    report.candidate = bundledProvenance(hashes);
    for (const name of [...new Set([...Object.keys(manifest.files), ...candidate.keys()])].sort()) {
      const baseline = manifest.files[name]?.toLowerCase();
      const next = hashes[name];
      const file = path.join(report.destination, name);
      checkPath(file);
      const current = stat(file);
      if (current && !current.isFile()) throw new Error(`Expected a regular file: ${name}`);
      const actual = current ? hash(fs.readFileSync(file)) : undefined;
      const customized = baseline !== undefined && actual !== baseline;
      const classification = baseline === undefined ? 'added' : customized && baseline !== next && actual !== next ? 'conflict' : customized ? 'customized' : next === undefined ? 'removed' : baseline === next ? 'unchanged' : 'updated';
      const collision = baseline === undefined && actual !== undefined;
      report.entries.push({ path: name, classification, installedSha256: actual, baselineSha256: baseline, candidateSha256: next,
        candidateChanged: baseline !== next, ...(actual === undefined ? { missing: true } : {}), ...(collision ? { collision: true } : {}) });
      if ((customized || collision) && report.status === 'ok') report.status = 'warning';
    }
  } catch (error) {
    report.status = 'error';
    report.findings.push({ code: 'preview-failed', message: error instanceof Error ? error.message : String(error) });
  }
  return report;
}
